try{lf_http_bootstrap($koneksi);}catch(DomainException $e){http_response_code(403);exit('Akun Super Admin aktif diperlukan.');}$actor=(int)$_SESSION['admin_id'];$unit=unit_active_id();$error='';$preview=null;$saved=false;$record=null;$payload=[];
